import FindExportPoliciesSettingsService from "../../service/exportPolicies/findExportPoliciesSettingsService";

class FindExportPoliciesSettingsController {
  /**
   * @constructor
   * @param {Worker} worker
   * @param {string} requestId
   * @param {ApiClientOptions} apiClientOptions the api client options
   */
  constructor(worker, requestId, apiClientOptions) {
    this.worker = worker;
    this.requestId = requestId;
    this.findExportPoliciesSettingsService = new FindExportPoliciesSettingsService(apiClientOptions);
  }

  /**
   * Controller executor.
   * @returns {Promise<void>}
   */
  async _exec() {
    try {
      const result = await this.exec();
      this.worker.port.emit(this.requestId, "SUCCESS", result);
    } catch (error) {
      console.error(error);
      this.worker.port.emit(this.requestId, "ERROR", error);
    }
  }

  /**
   * Find export policies settings.
   * @returns {Promise<ExportPoliciesSettingsEntity>} export policies settings
   */
  async exec() {
    return await this.findExportPoliciesSettingsService.find();
  }
}

export default FindExportPoliciesSettingsController;
